effect.shader:
void main(){
    vec4 src=texture2DCv(inputImg.texture, acScreenNorm);
    vec3 c=src.rgb;
    vec2 uv=acScreenNorm;
    float grid=0.0;
    if(uv.y < horizon){
        float z=1.0/max(horizon-uv.y, 0.001);
        float wx=(uv.x-0.5)*z;
        float wz=z + acTime*speed;
        float gx=abs(fract(wx)-0.5);
        float gz=abs(fract(wz)-0.5);
        float lw=0.03*z;
        grid=1.0-smoothstep(0.0, lw, min(gx,gz));
        grid*=clamp(z*0.15,0.0,1.0);
    }
    vec3 outc=1.0-(1.0-c)*(1.0-color.rgb*grid*amount);
    gl_FragColor=vec4(outc, src.a) + vec4(color.rgb*grid*amount,0.0)*(1.0-src.a);
}
